from typing import Any
import json
from datetime import datetime, timedelta

import pytest
from django.utils import timezone

from family_agent.runtime import HermesFamilyPlannerRuntime
from family_agent.tests.test_runtime import _create_admin_user
from organize.models import FamilyTask
from users.models import FamilyGroup


def _fixed_planner_now():
    return timezone.make_aware(datetime(2026, 1, 15, 12, 0, 0))


@pytest.mark.django_db
def test_runtime_today_prompt_mentions_organize_tooling_and_snapshots(monkeypatch: Any) -> None:
    family = FamilyGroup.objects.create(name="Planner Family")
    admin_user = _create_admin_user("today_tools_admin", family)
    now = _fixed_planner_now()
    monkeypatch.setattr("family_agent.tool_adapter.timezone.now", lambda: now)
    FamilyTask.objects.create(
        family=family,
        title="Pick up prescription",
        due_at=now + timedelta(hours=3),
        assigned_to=admin_user,
    )
    captured: dict[str, str] = {}

    class FakeAgent:
        def run_conversation(self, *, user_message: Any, system_message: Any) -> Any:
            captured["user_message"] = user_message
            captured["system_message"] = system_message
            return {
                "final_response": json.dumps(
                    {
                        "assistant_text": "Let's tackle today's tasks first.",
                        "citations": [],
                        "proposals": [],
                        "memory_suggestions": [],
                        "action_suggestions": [],
                    }
                ),
                "messages": [{"role": "user"}, {"role": "assistant"}],
                "task_id": "hermes-task-today-organize-1",
            }

    runtime = HermesFamilyPlannerRuntime()

    with pytest.MonkeyPatch.context() as monkeypatch:
        monkeypatch.setattr(runtime, "_build_agent", lambda: FakeAgent())
        result = runtime.execute(
            user=admin_user,
            family=family,
            message_text="What should I handle this week?",
            context_payload={
                "source_screen": "today",
                "today_section": "tasks",
                "planning_horizon": "this_week",
            },
        )

    assert result["assistant_text"] == "Let's tackle today's tasks first."
    assert "list_family_tasks" in captured["system_message"]
    assert "list_grocery_lists" in captured["system_message"]
    assert "list_chore_programs" in captured["system_message"]
    assert '"task_snapshot"' in captured["user_message"]


