        family=family,
        title="Return library books",
        due_at=now + timedelta(hours=2),
        assigned_to=admin_user,
    )
    prompts: list[str] = []

    class FakeAgent:
        def __init__(self) -> None:
            self.call_count = 0

        def run_conversation(
            self, *, user_message: Any, system_message: Any, conversation_history: Any=None
        ) -> Any:
            del system_message
            prompts.append(user_message)
            self.call_count += 1
            if self.call_count == 1:
                assert conversation_history is None
                return {
                    "final_response": json.dumps(
                        {
                            "assistant_text": "",
                            "citations": [],
                            "proposals": [],
                            "memory_suggestions": [],
                            "action_suggestions": [],
                            "tool_request": {
                                "name": "list_family_tasks",
                                "arguments": {
                                    "bucket": "today",
