    fake_agent = FakeAgent()

    with pytest.MonkeyPatch.context() as monkeypatch:
        monkeypatch.setattr(runtime, "_build_agent", lambda: fake_agent)
        result = runtime.execute(
            user=admin_user,
            family=family,
            message_text="What should I do first today?",
            context_payload={
                "source_screen": "today",
                "today_section": "tasks",
                "planning_horizon": "today",
            },
        )

    assert result["assistant_text"] == "Your top task is returning the library books."
    assert len(prompts) == 2
    assert '"tool_name": "list_family_tasks"' in prompts[1]
    assert "Return library books" in prompts[1]

