from typing import Any
from __future__ import annotations

from collections.abc import Iterable
from datetime import timedelta

from django.db.models import Q, QuerySet
from django.utils import timezone

from .models import GroceryItem

COMPLETED_ITEM_GRACE_PERIOD = timedelta(minutes=15)


def completed_item_cutoff(now: Any=None) -> Any:
    return (now or timezone.now()) - COMPLETED_ITEM_GRACE_PERIOD


def mobile_visible_items_q(now: Any=None) -> Q:
    cutoff = completed_item_cutoff(now)
    return (
        Q(is_completed=False)
        | Q(completed_at__gte=cutoff)
        | Q(
            is_completed=True,
            completed_at__isnull=True,
            updated_at__gte=cutoff,
        )
    )


def mobile_visible_item_queryset(
    queryset: QuerySet[GroceryItem], now: Any=None
) -> QuerySet[GroceryItem]:
    return queryset.filter(mobile_visible_items_q(now))


def filter_mobile_visible_items(
    items: Iterable[GroceryItem], now: Any=None
) -> list[GroceryItem]:
    cutoff = completed_item_cutoff(now)
    visible: list[GroceryItem] = []
    for item in items:
        if not item.is_completed:
            visible.append(item)
            continue

        completed_at = item.completed_at or item.updated_at
        if completed_at is None or completed_at >= cutoff:
            visible.append(item)

    return visible

